import schedule,datetime
real=schedule.datetime.datetime
class Fixed(real):
 @classmethod
 def now(cls,tz=None):return cls(2024,1,2,12,0,0)
schedule.datetime.datetime=Fixed
try:
 s=schedule.Scheduler();j=s.every().seconds.do(lambda:None);j.next_run=Fixed(2024,1,2,12,0,0);at=j.should_run;j.next_run=Fixed(2024,1,2,12,0,1);before=j.should_run;j.next_run=Fixed(2024,1,2,11,59,59);after=j.should_run;print('readiness',before,at,after);assert (before,at,after)==(False,True,True)
finally:schedule.datetime.datetime=real

from tornado import gen,ioloop
import tenacity
from tenacity.tornadoweb import TornadoRetrying
events=[];calls=[]
@gen.coroutine
def fn():
 calls.append(1);events.append('attempt'+str(len(calls)))
 if len(calls)==1:raise ValueError('retry')
 return 'done'
@gen.coroutine
def nap(delay):
 events.append(('sleep',float(delay)));yield gen.moment
r=TornadoRetrying(stop=tenacity.stop_after_attempt(2),wait=tenacity.wait_fixed(0),sleep=nap,reraise=True)
loop=ioloop.IOLoop();
try:value=loop.run_sync(lambda:r(fn))
finally:loop.close()
print('async_stages',events,'result',value);assert value=='done' and events==['attempt1',('sleep',0.0),'attempt2'],(value,events)

