from h11._writers import BodyWriter
from h11._events import Data,EndOfMessage
seen=[]
class Recorder(BodyWriter):
 def send_data(self,data,write):seen.append(('data',data))
 def send_eom(self,headers,write):seen.append(('eom',list(headers)))
w=Recorder();w(Data(data=b'x'),lambda _:None);w(EndOfMessage(),lambda _:None);print('writer_events',seen);assert seen==[('data',b'x'),('eom',[])],seen
